const CHEMISTRY_DP = [{"id": "3.1.1.1", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S1 - Chemical equilibrium", "code": "3.1.1.1", "descriptor": "Discriminate between open or closed chemical systems.", "graphical": false, "needsExplanation": true, "modelAnswer": ["An open system can exchange both matter and energy with its surroundings — e.g. a beaker of reacting solution open to the air, where gas can escape.", "A closed system can exchange energy with its surroundings but not matter — e.g. a sealed, rigid container — so nothing enters or leaves, but heat can still transfer in or out.", "Only closed systems can reach a true, stable state of dynamic equilibrium, because matter loss/gain in an open system continually shifts the amounts of reactants and products present."]}, {"id": "3.1.1.2", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S1 - Chemical equilibrium", "code": "3.1.1.2", "descriptor": "Identify that physical changes are usually reversible, whereas only some chemical reactions are reversible.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Physical changes (e.g. melting, boiling, dissolving) generally involve only weak intermolecular forces or physical states changing, so they can be reversed relatively easily by reversing the condition that caused them (e.g. cooling a melted solid).", "Chemical reactions involve breaking and forming (usually stronger) chemical bonds; many chemical changes go essentially to completion and are not readily reversed under normal conditions (e.g. combustion).", "Some chemical reactions are reversible — they can proceed in both the forward and reverse direction under suitable conditions — and it is specifically these reversible reactions that can establish a state of equilibrium."]}, {"id": "3.1.1.3", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S1 - Chemical equilibrium", "code": "3.1.1.3", "descriptor": "Symbolise equilibrium equations using ⇌ in balanced chemical equations.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.1.4", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S1 - Chemical equilibrium", "code": "3.1.1.4", "descriptor": "Explain observable properties and the characteristics of physical and chemical systems in a state of equilibrium.", "graphical": false, "needsExplanation": true, "modelAnswer": ["At equilibrium, measurable macroscopic properties (colour, pressure, concentration, pH etc.) remain constant over time, giving the appearance that the reaction has stopped.", "Microscopically, however, the forward and reverse reactions are both still occurring, at equal rates — this is why the system is described as being in dynamic (not static) equilibrium.", "Equilibrium can only be observed in a closed system; because the forward and reverse rates exactly balance, the net (observable) concentrations of reactants and products stop changing."]}, {"id": "3.1.1.5", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S1 - Chemical equilibrium", "code": "3.1.1.5", "descriptor": "Explain that, over time, physical change and reversible chemical reactions reach a state of dynamic equilibrium in a closed system, with the relative concentrations of products and reactants defining the position of equilibrium.", "graphical": false, "needsExplanation": true, "modelAnswer": ["In a closed system, a reversible reaction starts with mostly reactants; as the forward reaction proceeds, the reverse reaction rate increases (there is now more product to react back), while the forward rate decreases (less reactant remains).", "Eventually the forward and reverse rates become equal — the system has reached dynamic equilibrium, at which point the concentrations of reactants and products stop changing (even though both reactions continue).", "The 'position of equilibrium' describes whether reactants or products dominate at that constant state — a position that 'lies to the right' means mostly products are present, and 'to the left' means mostly reactants remain."]}, {"id": "3.1.1.6", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S1 - Chemical equilibrium", "code": "3.1.1.6", "descriptor": "Explain the reversibility of chemical reactions by considering the activation energies of the forward and reverse reactions.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A reaction is reversible when both the forward and reverse reactions have activation energies low enough to be overcome under the given conditions, so both directions can proceed at a measurable rate.", "If the reverse reaction's activation energy is far too high to be practically overcome (e.g. combustion products are very stable), the reaction effectively only proceeds forward and is considered irreversible in practice.", "The relative sizes of the forward and reverse activation energies (and how each responds to a temperature change) also help explain why increasing temperature affects the position of equilibrium in a predictable direction, favouring whichever direction has the larger activation energy."]}, {"id": "3.1.1.7", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S1 - Chemical equilibrium", "code": "3.1.1.7", "descriptor": "Analyse data and interpret graphical representations of relative changes in the concentration of reactants and product against time, to determine the position of equilibrium.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.2.1", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S2 - Factors that affect equilibrium", "code": "3.1.2.1", "descriptor": "Determine the effect of temperature change on chemical systems at equilibrium by considering the enthalpy change for the forward and reverse reactions.", "graphical": false, "needsExplanation": true, "modelAnswer": ["For an exothermic forward reaction (negative ΔH), increasing temperature favours the reverse (endothermic) direction, shifting equilibrium toward reactants — and decreasing temperature favours the forward direction, shifting equilibrium toward products.", "For an endothermic forward reaction (positive ΔH), the opposite applies: increasing temperature shifts equilibrium toward products, and decreasing temperature shifts it toward reactants.", "This can be reasoned about by treating heat as if it were a 'reactant' or 'product': increasing temperature effectively adds heat, so equilibrium shifts in the direction that absorbs that added heat (the endothermic direction)."]}, {"id": "3.1.2.2", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S2 - Factors that affect equilibrium", "code": "3.1.2.2", "descriptor": "Explain the effect of changes of temperature, concentration and pressure on chemical systems at equilibrium by applying collision theory to the forward and reverse reactions.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Increasing concentration of a reactant increases the frequency of successful collisions between reacting particles for the forward reaction, temporarily increasing the forward rate more than the reverse rate, shifting the position of equilibrium toward products until a new balance of rates is reached.", "Increasing pressure (for reactions involving gases) increases the concentration of all gaseous species, favouring collisions and shifting equilibrium toward the side with fewer moles of gas, since that side can 're-balance' the increased collision frequency more effectively.", "Increasing temperature increases the average kinetic energy of particles, increasing the rate of both the forward and reverse reactions, but increases the rate of the endothermic direction more than the exothermic direction, shifting the equilibrium position toward the endothermic side."]}, {"id": "3.1.2.3", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S2 - Factors that affect equilibrium", "code": "3.1.2.3", "descriptor": "Apply Le Châtelier's principle to determine the effect changes of temperature, concentration of chemicals, pressure and the addition of a catalyst have on the position of equilibrium and on the value of the equilibrium constant.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Le Châtelier's principle states that if a system at equilibrium is disturbed (by a change in concentration, temperature or pressure), the system will shift in the direction that partially counteracts (opposes) that disturbance, reaching a new equilibrium position.", "Changing concentration or pressure shifts the position of equilibrium but does NOT change the value of the equilibrium constant (Kc) at a given temperature — only the relative amounts of reactants/products at the new equilibrium change, not the ratio expressed by Kc.", "Changing temperature is the only listed factor that actually changes the value of Kc itself, since Kc is temperature-dependent — it shifts the equilibrium position by genuinely favouring one direction's rate over the other's, as reflected in a new equilibrium constant value.", "Adding a catalyst speeds up both the forward and reverse reactions equally, so the system reaches equilibrium faster, but it does NOT shift the position of equilibrium or change the value of Kc."]}, {"id": "3.1.3.1", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S3 - Equilibrium constants", "code": "3.1.3.1", "descriptor": "Identify that the equilibrium constant (Kc) indicates the relationship between product and reactant concentrations at equilibrium.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Kc is a numerical value calculated from the concentrations of products and reactants at equilibrium, according to the balanced chemical equation.", "A large Kc value (>>1) indicates that, at equilibrium, products are strongly favoured (the equilibrium position lies well to the right).", "A small Kc value (<<1) indicates that reactants are strongly favoured at equilibrium (the position lies well to the left)."]}, {"id": "3.1.3.2", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S3 - Equilibrium constants", "code": "3.1.3.2", "descriptor": "Identify that the solubility product (Ksp) gives a measure of the solubility of an ionic compound.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Ksp is a special type of equilibrium constant that applies to the dissolution of a sparingly soluble ionic compound in water.", "A larger Ksp value indicates a more soluble compound (more of the solid dissolves before equilibrium between the solid and its dissolved ions is reached), while a smaller Ksp indicates a less soluble compound.", "Because Ksp is derived from an equilibrium expression, it can be used to calculate the actual solubility (in mol/L or g/L) of the ionic compound in water."]}, {"id": "3.1.3.3", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S3 - Equilibrium constants", "code": "3.1.3.3", "descriptor": "Determine the equilibrium law expression for homogeneous and heterogeneous systems.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.3.4", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S3 - Equilibrium constants", "code": "3.1.3.4", "descriptor": "Determine the extent of a reaction from the magnitude of the equilibrium constant (Kc).", "graphical": false, "needsExplanation": true, "modelAnswer": ["If Kc is very large, the reaction proceeds nearly to completion — almost all reactants are converted to products by the time equilibrium is reached.", "If Kc is very small, the reaction barely proceeds — the reactants remain largely unreacted at equilibrium, with only a small amount of product formed.", "If Kc is close to 1, significant (comparable) amounts of both reactants and products are present at equilibrium, indicating a reaction that proceeds only partway before establishing equilibrium."]}, {"id": "3.1.3.5", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S3 - Equilibrium constants", "code": "3.1.3.5", "descriptor": "Calculate the reaction quotient (Q) for reversible reactions.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.3.6", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S3 - Equilibrium constants", "code": "3.1.3.6", "descriptor": "Calculate equilibrium constants (Kc) and the concentrations of reactants and products. Assume [reactants]initial = [reactants]equilibrium when Kc is very small and state assumption when used.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.3.7", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S3 - Equilibrium constants", "code": "3.1.3.7", "descriptor": "Calculate solubility products (Ksp) and the concentrations of ions in aqueous solutions.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.3.8", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S3 - Equilibrium constants", "code": "3.1.3.8", "descriptor": "Infer shifts in equilibrium reactions using equilibrium constants (Kc) and reaction quotients (Q).", "graphical": false, "needsExplanation": true, "modelAnswer": ["The reaction quotient Q is calculated using the same expression as Kc, but with the current (not necessarily equilibrium) concentrations of reactants and products at a given moment.", "If Q < Kc, there is proportionally too much reactant relative to product compared with equilibrium, so the reaction will shift forward (toward products) until Q rises to equal Kc.", "If Q > Kc, there is proportionally too much product relative to reactant, so the reaction will shift in reverse (toward reactants) until Q falls to equal Kc.", "If Q = Kc, the system is already at equilibrium and no net shift will occur."]}, {"id": "3.1.3.9", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S3 - Equilibrium constants", "code": "3.1.3.9", "descriptor": "Analyse data to determine reaction quotients (Q), equilibrium constants (Kc), the concentrations of reactants and products and the concentration of ions in aqueous solutions.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.4.1", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S4 - Properties of acids and bases", "code": "3.1.4.1", "descriptor": "Identify that acids are substances that can act as proton (hydrogen ion) donors.", "graphical": false, "needsExplanation": true, "modelAnswer": ["This is the Brønsted-Lowry definition of an acid: a substance capable of donating a hydrogen ion (H⁺, a proton) to another species in a reaction.", "For an acid to donate a proton, it must contain at least one ionisable hydrogen atom.", "This definition applies more broadly than the traditional idea of acids only being aqueous, since it focuses on the proton-transfer role a substance plays in a reaction."]}, {"id": "3.1.4.2", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S4 - Properties of acids and bases", "code": "3.1.4.2", "descriptor": "Identify acids as monoprotic, diprotic or polyprotic.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Monoprotic acids can donate only one proton per molecule (e.g. HCl, CH₃COOH).", "Diprotic acids can donate two protons per molecule, typically in two successive ionisation steps (e.g. H₂SO₄, H₂CO₃).", "Polyprotic acids can donate more than one proton in general (including diprotic acids as a subset), and includes acids able to donate three or more protons (e.g. H₃PO₄, which is triprotic)."]}, {"id": "3.1.4.3", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S4 - Properties of acids and bases", "code": "3.1.4.3", "descriptor": "Identify hydrochloric, nitric and sulfuric acid as strong acids and group 1 hydroxides and barium hydroxide as strong bases.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Strong acids (HCl, HNO₃, H₂SO₄) are considered to ionise essentially completely in water, producing a high concentration of H₃O⁺ ions relative to the initial acid concentration.", "Strong bases — the group 1 metal hydroxides (e.g. NaOH, KOH) and barium hydroxide (Ba(OH)₂) — similarly dissociate essentially completely in water, producing a high concentration of OH⁻ ions.", "Being 'strong' in this context refers specifically to the extent of ionisation/dissociation, not to concentration — a strong acid can still be present in a dilute solution."]}, {"id": "3.1.4.4", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S4 - Properties of acids and bases", "code": "3.1.4.4", "descriptor": "Identify carboxylic and carbonic acids as weak acids and ammonia and amines as weak bases.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Weak acids (e.g. carboxylic acids like ethanoic acid, and carbonic acid H₂CO₃) only partially ionise in water, establishing an equilibrium between the un-ionised acid and its ions rather than ionising completely.", "Weak bases (e.g. ammonia and amines) similarly only partially react with water to form OH⁻ ions, establishing an equilibrium rather than reacting to completion.", "Because only a small proportion of weak acid/base molecules ionise at any moment, solutions of weak acids/bases have a less extreme pH than a strong acid/base of the same concentration."]}, {"id": "3.1.4.5", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S4 - Properties of acids and bases", "code": "3.1.4.5", "descriptor": "Discriminate between the terms strong, weak, concentrated and dilute for acids and bases.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Strong/weak describes the EXTENT of ionisation of the acid or base in water — strong acids/bases ionise essentially completely, weak ones only partially (an equilibrium property).", "Concentrated/dilute describes the AMOUNT of acid or base dissolved per unit volume of solution — a large amount of solute per litre is concentrated, a small amount is dilute (independent of strength).", "These two properties are independent: it's possible to have a concentrated weak acid (a lot of a weak acid dissolved) or a dilute strong acid (a small amount of a strong acid dissolved), and each combination behaves differently."]}, {"id": "3.1.4.6", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S4 - Properties of acids and bases", "code": "3.1.4.6", "descriptor": "Discriminate between strong and weak acids and bases in terms of the extent of dissociation, rate of reaction, pH and electrical conductivity.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Extent of dissociation: strong acids/bases dissociate essentially 100%; weak acids/bases dissociate only partially, reaching an equilibrium.", "Rate of reaction: for the same concentration, strong acids/bases generally react faster with other substances (e.g. metals, carbonates) because they provide a higher concentration of reactive H⁺ or OH⁻ ions.", "pH: a strong acid/base produces a more extreme pH (further from 7) than a weak acid/base at the same concentration, since more ions are produced.", "Electrical conductivity: strong acids/bases conduct electricity more strongly than weak acids/bases of the same concentration, because they produce a higher concentration of free-moving ions in solution."]}, {"id": "3.1.4.7", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S4 - Properties of acids and bases", "code": "3.1.4.7", "descriptor": "Analyse data to determine the strength, concentration, pH and electrical conductivity of acids and bases.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.5.1", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S5 - pH", "code": "3.1.5.1", "descriptor": "Identify that water is a weak electrolyte and the self-ionisation of water is represented by Kw. (Formula: Kw = [H+][OH–])", "graphical": false, "needsExplanation": true, "modelAnswer": ["Pure water undergoes a very small degree of self-ionisation, producing equal (small) concentrations of H⁺ and OH⁻ ions, which is why it conducts electricity only very weakly.", "The equilibrium constant for this self-ionisation, Kw = [H⁺][OH⁻], has a fixed value at a given temperature (≈1.0 × 10⁻¹⁴ at 25°C).", "Because Kw is constant at a given temperature, [H⁺] and [OH⁻] are always inversely related in any aqueous solution — knowing one lets you calculate the other."]}, {"id": "3.1.5.2", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S5 - pH", "code": "3.1.5.2", "descriptor": "Apply Kw to calculate the concentration of hydrogen ions from the concentration of hydroxide ions in a solution.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.5.3", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S5 - pH", "code": "3.1.5.3", "descriptor": "Calculate pH, hydrogen ion concentration [H+(aq)], pOH and hydroxide ion concentrations [OH–(aq)] for strong acids and bases. (Formula: pH = –log10 [H+] and pOH = –log10[OH–])", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.6.1", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S6 - Brønsted-Lowry model", "code": "3.1.6.1", "descriptor": "Describe acids and bases in equilibrium systems using the Brønsted-Lowry model.", "graphical": false, "needsExplanation": true, "modelAnswer": ["In the Brønsted-Lowry model, an acid-base reaction is a proton (H⁺) transfer: the acid donates a proton and the base accepts it.", "Because many acid-base reactions in aqueous solution are reversible, this proton transfer can be represented as an equilibrium, using the ⇌ symbol, between the original acid/base and the newly formed conjugate species.", "This model extends the idea of acids and bases beyond substances that simply contain H⁺ or OH⁻ explicitly, since it defines acids and bases by their proton-donating or -accepting behaviour in a specific reaction."]}, {"id": "3.1.6.2", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S6 - Brønsted-Lowry model", "code": "3.1.6.2", "descriptor": "Explain the Brønsted-Lowry model using chemical equations that illustrate the transfer of hydrogen ions (protons) between conjugate acid-base pairs.", "graphical": false, "needsExplanation": true, "modelAnswer": ["When an acid (HA) donates a proton to a base (B), it becomes its conjugate base (A⁻), and the base becomes its conjugate acid (BH⁺): HA + B ⇌ A⁻ + BH⁺.", "A conjugate acid-base pair differs by exactly one proton (H⁺) — e.g. HA and A⁻ form one conjugate pair, and B and BH⁺ form the other conjugate pair in the same reaction.", "In a reversible reaction, the same proton-transfer logic applies in the reverse direction: the conjugate acid (BH⁺) can donate its proton back to the conjugate base (A⁻), regenerating the original acid and base."]}, {"id": "3.1.6.3", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S6 - Brønsted-Lowry model", "code": "3.1.6.3", "descriptor": "Identify that amphiprotic species can act as Brønsted-Lowry acid (or base).", "graphical": false, "needsExplanation": true, "modelAnswer": ["An amphiprotic species (e.g. HCO₃⁻, H₂O, HSO₄⁻) contains a hydrogen atom it can donate (acting as an acid) but can also accept a proton (acting as a base), depending on what it is reacting with.", "Which role it plays in a given reaction depends on the relative acid/base strength of the other species present — it acts as an acid when reacting with a stronger base, and as a base when reacting with a stronger acid.", "Water is a common example: it acts as a base when reacting with an acid (accepting a proton to form H₃O⁺) and as an acid when reacting with a base (donating a proton to form OH⁻)."]}, {"id": "3.1.6.4", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S6 - Brønsted-Lowry model", "code": "3.1.6.4", "descriptor": "Determine the formula of the conjugate acid (or base) of any Brønsted-Lowry base (or acid).", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.6.5", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S6 - Brønsted-Lowry model", "code": "3.1.6.5", "descriptor": "Identify that buffers are solutions that are conjugate in nature and resist a change in pH when a small amount of an acid or base is added. (Buffer calculations are not required.)", "graphical": false, "needsExplanation": true, "modelAnswer": ["A buffer solution contains a conjugate acid-base pair in significant, comparable concentrations (e.g. a weak acid and its conjugate base, such as CH₃COOH/CH₃COO⁻).", "Because both the weak acid and its conjugate base are present in reasonable amounts, the buffer can neutralise a small addition of either H⁺ (using the conjugate base component) or OH⁻ (using the weak acid component).", "This neutralising capacity is why the buffer's pH changes only slightly when a small amount of strong acid or base is added, compared with the large pH change the same addition would cause in pure water."]}, {"id": "3.1.6.6", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S6 - Brønsted-Lowry model", "code": "3.1.6.6", "descriptor": "Apply Le Châtelier's principle to explain how buffer solutions respond to the addition of hydrogen ions and hydroxide ions.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Adding H⁺ ions to a buffer disturbs the acid-base equilibrium (HA ⇌ H⁺ + A⁻) by increasing [H⁺]; by Le Châtelier's principle, the equilibrium shifts left, consuming most of the added H⁺ as it reacts with the conjugate base A⁻ to reform HA — limiting the pH change.", "Adding OH⁻ ions removes H⁺ from solution (by reacting to form water), which disturbs the same equilibrium by decreasing [H⁺]; the equilibrium then shifts right, with more HA ionising to replace the H⁺ that was removed — again limiting the pH change.", "In both cases, the presence of a reasonable concentration of both HA and A⁻ (the conjugate pair) means the buffer equilibrium can shift substantially in either direction while only slightly changing the equilibrium [H⁺], keeping pH relatively stable."]}, {"id": "3.1.7.1", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S7 - Dissociation constants", "code": "3.1.7.1", "descriptor": "Explain that the strength of acids is related to the degree of ionisation at equilibrium in aqueous solution.", "graphical": false, "needsExplanation": true, "modelAnswer": ["An acid's strength refers to the proportion of its molecules that ionise (donate a proton to water) once dissolved, at equilibrium.", "A strong acid has a very high degree of ionisation (approaching 100%), meaning the equilibrium lies almost entirely toward the ionised (dissociated) form.", "A weak acid has a low degree of ionisation, meaning the equilibrium lies mostly toward the un-ionised (molecular) form, with only a small fraction of molecules dissociated at any time."]}, {"id": "3.1.7.2", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S7 - Dissociation constants", "code": "3.1.7.2", "descriptor": "Identify that the strength of acids can be represented with chemical equations and equilibrium constants (Ka).", "graphical": false, "needsExplanation": true, "modelAnswer": ["The ionisation of a weak acid in water can be written as a reversible reaction (an equilibrium), e.g. HA + H₂O ⇌ H₃O⁺ + A⁻.", "The equilibrium constant for this ionisation, Ka, quantifies the acid's strength: a larger Ka indicates a greater degree of ionisation (a stronger weak acid), and a smaller Ka indicates a lesser degree of ionisation (a weaker acid).", "Because strong acids ionise essentially completely, their Ka values are not meaningfully defined/measured in the same way (they are treated as ionising fully rather than reaching a measurable equilibrium)."]}, {"id": "3.1.7.3", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S7 - Dissociation constants", "code": "3.1.7.3", "descriptor": "Determine the expression for the dissociation constant for weak acids (Ka) and weak bases (Kb) from balanced chemical equations.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.7.4", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S7 - Dissociation constants", "code": "3.1.7.4", "descriptor": "Calculate dissociation constants (Ka, Kb, and Kw), pKa, pKb, and the concentrations of reactants and products.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.7.5", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S7 - Dissociation constants", "code": "3.1.7.5", "descriptor": "Analyse data to compare the relative strengths of acids and bases.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.8.1", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S8 - Acid-base indicators", "code": "3.1.8.1", "descriptor": "Identify that acid-base indicators are a weak acid or a weak base where the conjugate acid-base pair have different colours and can be represented by HIn(aq) ⇌ H+(aq) + In−(aq) or BOH(aq) ⇌ B+(aq) + OH−(aq).", "graphical": false, "needsExplanation": true, "modelAnswer": ["An indicator is itself a weak acid (HIn) or weak base (BOH) whose un-ionised form and ionised (conjugate) form have visibly different colours.", "In solution, the indicator establishes its own acid-base equilibrium (e.g. HIn ⇌ H⁺ + In⁻); the observed colour depends on which form — HIn or In⁻ — dominates in that equilibrium mixture.", "Because the position of this equilibrium depends on the surrounding solution's [H⁺], the indicator's observed colour changes as the pH of the surrounding solution changes."]}, {"id": "3.1.8.2", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S8 - Acid-base indicators", "code": "3.1.8.2", "descriptor": "Identify that indicators change colour when pH = pKa.", "graphical": false, "needsExplanation": true, "modelAnswer": ["At pH = pKa of the indicator, the concentrations of the indicator's two forms (HIn and In⁻) are equal, so the observed colour is an intermediate mix of both pure colours (the transition point).", "As pH moves away from this point in either direction, one form increasingly dominates, and the solution's colour shifts increasingly toward that form's pure colour.", "This is why pKa is used as the reference point for describing an indicator's colour-change behaviour with pH."]}, {"id": "3.1.8.3", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S8 - Acid-base indicators", "code": "3.1.8.3", "descriptor": "Explain the relationship between the pH range, the end point and the pKa value of an acid-base indicator.", "graphical": false, "needsExplanation": true, "modelAnswer": ["An indicator's colour change is visible to the human eye over an approximate pH range of pKa ± 1, since outside this range one form so strongly dominates that no further visible colour shift occurs.", "The end point of a titration is the pH at which the indicator visibly changes colour — ideally this should occur very close to the pKa of the indicator, at the midpoint of its colour-change range.", "For the end point to closely match the true equivalence point of the titration, an indicator should be chosen whose pKa lies within (or very close to) the pH range through which the titration curve rises steeply at the equivalence point."]}, {"id": "3.1.8.4", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S8 - Acid-base indicators", "code": "3.1.8.4", "descriptor": "Analyse data to determine an appropriate indicator given the equivalence point of the titration and the pH range of the indicator (assuming indicators change colour over a range of pKa ± 1).", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.9.1", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S9 - Volumetric analysis", "code": "3.1.9.1", "descriptor": "Discriminate between the terms end point and equivalence point.", "graphical": false, "needsExplanation": true, "modelAnswer": ["The equivalence point is the theoretical point in a titration at which the moles of acid and base added are exactly stoichiometrically equal (chemically 'complete' neutralisation).", "The end point is the point at which the indicator used actually changes colour, signalling to the experimenter that the titration should be stopped.", "Ideally, a well-chosen indicator gives an end point that is very close to (though not always exactly identical to) the true equivalence point — the difference between the two represents a source of small experimental (indicator) error."]}, {"id": "3.1.9.2", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S9 - Volumetric analysis", "code": "3.1.9.2", "descriptor": "Sketch the general shapes of conductometric and acid-base titration curves involving strong and weak acids and bases. (Titration of weak acids to weak bases is not required.)", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.9.3", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S9 - Volumetric analysis", "code": "3.1.9.3", "descriptor": "Interpret acid-base titration curves to determine the intercept with pH axis, equivalence point, buffer region and points where pKa = pH or pKb = pOH.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.9.4", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S9 - Volumetric analysis", "code": "3.1.9.4", "descriptor": "Interpret conductometric titration curves to determine the intercept with conductivity axis, equivalence point and volume of titrant.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.9.5", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S9 - Volumetric analysis", "code": "3.1.9.5", "descriptor": "Analyse volumetric data, including solubility, conductometric and acid-base titration curves, to determine moles, mass, volume and concentration.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.9.6", "unit": 3, "topic": "T1 - Chemical equilibrium systems", "subtopic": "S9 - Volumetric analysis", "code": "3.1.9.6", "descriptor": "Analyse titration curves to calculate the concentration of a solution with reference to a standard solution.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.1.1", "unit": 3, "topic": "T2 - Oxidation and reduction", "subtopic": "S1 - Redox reactions", "code": "3.2.1.1", "descriptor": "Identify that displacement reactions of metals, combustion, corrosion and electrochemical processes, can be modelled as redox reactions involving oxidation of one substance and reduction of another substance.", "graphical": false, "needsExplanation": true, "modelAnswer": ["In each of these processes, one species loses electrons (is oxidised) while another simultaneously gains electrons (is reduced) — the two half-processes always occur together.", "Metal displacement reactions: a more reactive metal is oxidised (loses electrons, forms a cation) while a less reactive metal ion is reduced (gains electrons, forms the neutral metal).", "Combustion and corrosion both typically involve a fuel or metal being oxidised while oxygen (or another oxidant) is reduced, releasing (combustion) or slowly transferring (corrosion) energy in the process."]}, {"id": "3.2.1.2", "unit": 3, "topic": "T2 - Oxidation and reduction", "subtopic": "S1 - Redox reactions", "code": "3.2.1.2", "descriptor": "Determine the species oxidised and reduced, and the oxidising agent and reducing agent, in redox reactions.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.1.3", "unit": 3, "topic": "T2 - Oxidation and reduction", "subtopic": "S1 - Redox reactions", "code": "3.2.1.3", "descriptor": "Explain that oxidation can be modelled as the loss of electrons from a chemical species, and reduction can be modelled as the gain of electrons by a chemical species; these processes can be represented using balanced half-equations and redox equations (acidic conditions only).", "graphical": false, "needsExplanation": true, "modelAnswer": ["Oxidation is the loss of electrons by a species (its oxidation state increases); reduction is the gain of electrons by a species (its oxidation state decreases) — remembered via 'OIL RIG' (Oxidation Is Loss, Reduction Is Gain).", "Because electrons lost by one species must be gained by another, oxidation and reduction always occur together in a redox reaction — one cannot happen without the other.", "Each half-reaction (oxidation and reduction separately) can be written as a balanced half-equation showing the electrons explicitly; adding the two half-equations together (after balancing electrons transferred) gives the overall balanced redox equation."]}, {"id": "3.2.1.4", "unit": 3, "topic": "T2 - Oxidation and reduction", "subtopic": "S1 - Redox reactions", "code": "3.2.1.4", "descriptor": "Determine the oxidation state (represented with the sign given before the number) of an atom in an ion or compound, e.g. +2.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.1.5", "unit": 3, "topic": "T2 - Oxidation and reduction", "subtopic": "S1 - Redox reactions", "code": "3.2.1.5", "descriptor": "Apply oxidation numbers (represented as roman numerals) to name transition metal compounds.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.1.6", "unit": 3, "topic": "T2 - Oxidation and reduction", "subtopic": "S1 - Redox reactions", "code": "3.2.1.6", "descriptor": "Apply half-equations and oxidation numbers to balance redox equations (acid conditions only) and to discriminate between the species oxidised and reduced, and the oxidising agent and reducing agent.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.1.7", "unit": 3, "topic": "T2 - Oxidation and reduction", "subtopic": "S1 - Redox reactions", "code": "3.2.1.7", "descriptor": "Analyse data, including displacement reactions of metals, combustion, corrosion and electrochemical processes to determine redox reactions.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.2.1", "unit": 3, "topic": "T2 - Oxidation and reduction", "subtopic": "S2 - Electrochemical cells", "code": "3.2.2.1", "descriptor": "Explain that electrochemical cells, including galvanic and electrolytic cells, consist of oxidation and reduction half-reactions connected via an external circuit that allows electrons to move from the anode (oxidation reaction) to the cathode (reduction reaction).", "graphical": false, "needsExplanation": true, "modelAnswer": ["In both galvanic and electrolytic cells, the oxidation half-reaction and reduction half-reaction are physically separated into two half-cells, connected by an external wire.", "This physical separation forces the electrons released during oxidation to travel through the external circuit (rather than transferring directly between species) to reach the site of reduction, which is what allows the electron flow to be measured or driven as an electric current.", "By convention, the electrode where oxidation occurs is always called the anode, and the electrode where reduction occurs is always called the cathode — in every type of electrochemical cell."]}, {"id": "3.2.2.2", "unit": 3, "topic": "T2 - Oxidation and reduction", "subtopic": "S2 - Electrochemical cells", "code": "3.2.2.2", "descriptor": "Discriminate between a galvanic and an electrolytic cell.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A galvanic (voltaic) cell contains a spontaneous redox reaction, which itself generates electrical energy — chemical energy is converted into electrical energy.", "An electrolytic cell requires an external power source (e.g. a battery) to force a non-spontaneous redox reaction to occur — electrical energy is converted into chemical energy.", "Despite this key difference, both cell types share the same basic components (two electrodes, an electrolyte, oxidation at the anode and reduction at the cathode)."]}, {"id": "3.2.3.1", "unit": 3, "topic": "T2 - Oxidation and reduction", "subtopic": "S3 - Galvanic cells", "code": "3.2.3.1", "descriptor": "Identify that galvanic cells generate an electrical potential difference from a spontaneous redox reaction.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A galvanic cell physically separates a spontaneous redox reaction into two half-cells, forcing electron transfer to occur via an external circuit rather than by direct contact.", "The overall tendency of the spontaneous reaction to proceed (release energy) drives electrons from the anode to the cathode through this circuit, creating a measurable potential difference (voltage) between the two electrodes.", "This potential difference can be used to do electrical work — this is the basic operating principle behind batteries."]}, {"id": "3.2.3.2", "unit": 3, "topic": "T2 - Oxidation and reduction", "subtopic": "S3 - Galvanic cells", "code": "3.2.3.2", "descriptor": "Explain that galvanic cells can be represented as cell diagrams, including anode and cathode half-equations.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A cell diagram (cell notation) is a shorthand way of representing the components and set-up of a galvanic cell using symbols, without needing a full drawing.", "By convention, the anode (oxidation) half-cell is written on the left and the cathode (reduction) half-cell on the right, separated by a double vertical line (||) representing the salt bridge, with single lines (|) separating different phases within each half-cell.", "Alongside (or instead of) the cell diagram, the separate oxidation and reduction half-equations can be written out explicitly, showing electrons transferred at each electrode."]}, {"id": "3.2.3.3", "unit": 3, "topic": "T2 - Oxidation and reduction", "subtopic": "S3 - Galvanic cells", "code": "3.2.3.3", "descriptor": "Explain that oxidation occurs at the negative electrode (anode) and reduction occurs at the positive electrode (cathode).", "graphical": false, "needsExplanation": true, "modelAnswer": ["In a galvanic cell, the anode is the electrode where oxidation (electron loss) occurs; because electrons are released there and flow away through the external circuit, this electrode is designated the negative electrode.", "The cathode is the electrode where reduction (electron gain) occurs; because electrons flow into it from the circuit, this electrode is designated the positive electrode.", "This polarity assignment (anode = negative, cathode = positive) applies specifically to galvanic cells; note that in electrolytic cells the polarity convention for anode/cathode is reversed, though the anode is still where oxidation occurs and the cathode is still where reduction occurs."]}, {"id": "3.2.3.4", "unit": 3, "topic": "T2 - Oxidation and reduction", "subtopic": "S3 - Galvanic cells", "code": "3.2.3.4", "descriptor": "Explain that two half-cells can be connected by a salt bridge to create a galvanic cell, e.g. Mg, Zn, Fe and Cu and solutions of their ions.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A salt bridge is a tube or strip containing an inert electrolyte solution (e.g. in a gel) that connects the two half-cells, completing the internal circuit without letting the two half-cell solutions mix directly.", "As electrons flow through the external wire from anode to cathode, positive charge builds up in the anode half-cell (from newly formed metal cations) and negative charge builds up in the cathode half-cell (from consumed cations); the salt bridge allows ions to migrate to balance this charge buildup.", "Without the salt bridge, charge would rapidly build up in each half-cell and stop electron flow almost immediately — the salt bridge is what allows the cell to sustain a continuous current."]}, {"id": "3.2.3.5", "unit": 3, "topic": "T2 - Oxidation and reduction", "subtopic": "S3 - Galvanic cells", "code": "3.2.3.5", "descriptor": "Identify the essential components of a galvanic cell, including the oxidation and reduction half-cells, the positive and negative electrodes and their solutions of their ions, the flow of electrons and the movement of ions, and the salt bridge.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Essential components: two separate half-cells (one for oxidation, one for reduction), each usually consisting of a metal electrode immersed in a solution of its own ions; an external wire connecting the two electrodes; and a salt bridge connecting the two solutions.", "Electrons flow through the external wire, from the anode (negative electrode, oxidation) to the cathode (positive electrode, reduction).", "Ions flow through the salt bridge (cations moving toward the cathode half-cell, anions moving toward the anode half-cell) to maintain overall charge neutrality in each half-cell as the reaction proceeds."]}, {"id": "3.2.3.6", "unit": 3, "topic": "T2 - Oxidation and reduction", "subtopic": "S3 - Galvanic cells", "code": "3.2.3.6", "descriptor": "Sketch a galvanic cell and label the essential components.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.4.1", "unit": 3, "topic": "T2 - Oxidation and reduction", "subtopic": "S4 - Standard electrode potential", "code": "3.2.4.1", "descriptor": "Describe the standard hydrogen electrode.", "graphical": false, "needsExplanation": true, "modelAnswer": ["The standard hydrogen electrode (SHE) consists of hydrogen gas (at 1 atm/100 kPa) bubbled over an inert platinum electrode, immersed in a 1 mol/L solution of H⁺ ions, at 25°C.", "By international convention, the SHE is assigned a standard electrode (reduction) potential of exactly 0 V, serving as the reference point against which all other standard electrode potentials are measured.", "Because it is a defined reference (rather than an absolute measurement), all E° values reported for other half-cells are really measured relative to this hydrogen electrode standard."]}, {"id": "3.2.4.2", "unit": 3, "topic": "T2 - Oxidation and reduction", "subtopic": "S4 - Standard electrode potential", "code": "3.2.4.2", "descriptor": "Explain the term standard electrode (reduction) potential, E°.", "graphical": false, "needsExplanation": true, "modelAnswer": ["E° is the potential difference (voltage) generated by a half-cell operating under standard conditions (1 mol/L solute concentrations, 100 kPa gas pressure, 25°C) when connected to a standard hydrogen electrode, with the half-reaction written as a reduction.", "A more positive E° indicates a greater tendency for that half-reaction to occur as written (as a reduction) — i.e. a stronger oxidising agent.", "A more negative E° indicates a lesser tendency to be reduced (or a greater tendency to be oxidised instead) — i.e. a stronger reducing agent."]}, {"id": "3.2.4.3", "unit": 3, "topic": "T2 - Oxidation and reduction", "subtopic": "S4 - Standard electrode potential", "code": "3.2.4.3", "descriptor": "Identify the limitations associated with standard electrode (reduction) potentials, E°.", "graphical": false, "needsExplanation": true, "modelAnswer": ["E° values are only strictly valid under standard conditions (1 mol/L concentration, 100 kPa, 25°C); at other concentrations, temperatures or pressures, the actual cell potential can differ from the standard value.", "E° values indicate the thermodynamic tendency (spontaneity) of a reaction, but say nothing about the rate at which that reaction actually proceeds — a reaction can be thermodynamically favoured (positive Ecell) yet occur extremely slowly in practice.", "E° values are typically measured/tabulated for reactions in aqueous solution and may not directly apply to reactions in non-aqueous solvents or at electrode surfaces with significant side reactions (e.g. overpotential effects during electrolysis)."]}, {"id": "3.2.4.4", "unit": 3, "topic": "T2 - Oxidation and reduction", "subtopic": "S4 - Standard electrode potential", "code": "3.2.4.4", "descriptor": "Calculate cell potential, Ecell. (Formula: E°cell = E°reduction half-cell − E°oxidation half-cell)", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.4.5", "unit": 3, "topic": "T2 - Oxidation and reduction", "subtopic": "S4 - Standard electrode potential", "code": "3.2.4.5", "descriptor": "Apply standard electrode potentials to determine the relative strength of oxidising and reducing agents.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.4.6", "unit": 3, "topic": "T2 - Oxidation and reduction", "subtopic": "S4 - Standard electrode potential", "code": "3.2.4.6", "descriptor": "Analyse data, including standard electrode potentials, to make predictions about the spontaneity of a reaction and to compare electrochemical cells.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.5.1", "unit": 3, "topic": "T2 - Oxidation and reduction", "subtopic": "S5 - Electrolytic cells", "code": "3.2.5.1", "descriptor": "Identify that electrolytic cells use an external electrical potential difference to provide the energy to allow a non-spontaneous redox reaction to occur.", "graphical": false, "needsExplanation": true, "modelAnswer": ["In an electrolytic cell, the redox reaction taking place would not occur spontaneously on its own (it has a negative overall cell potential under the given conditions).", "An external power source (e.g. a battery or power supply) forces electrons to flow in the required (non-spontaneous) direction, effectively 'paying' the energy cost needed to drive the reaction.", "This conversion of electrical energy into chemical energy (the reverse of what happens in a galvanic cell) is the defining feature of electrolysis."]}, {"id": "3.2.5.2", "unit": 3, "topic": "T2 - Oxidation and reduction", "subtopic": "S5 - Electrolytic cells", "code": "3.2.5.2", "descriptor": "Identify the essential components of an electrolytic cell, including source of electric current and conductors, positive and negative electrodes, and the electrolyte.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Essential components: an external power source (DC), connecting wires (conductors), two electrodes, and an electrolyte (a molten ionic compound or an aqueous ionic solution) that both electrodes are immersed in.", "Unlike a galvanic cell, both electrodes are typically immersed in the same single electrolyte, rather than being in two physically separate half-cells joined by a salt bridge.", "The electrolyte must contain mobile ions so that current can flow through the solution/melt between the two electrodes, completing the circuit."]}, {"id": "3.2.5.3", "unit": 3, "topic": "T2 - Oxidation and reduction", "subtopic": "S5 - Electrolytic cells", "code": "3.2.5.3", "descriptor": "State the factors that affect the products in electrolysis.", "graphical": false, "needsExplanation": true, "modelAnswer": ["The nature of the electrolyte (which ions are actually present) determines which species are available to be oxidised or reduced at each electrode.", "Whether the electrolyte is molten or aqueous matters — in aqueous solutions, water itself can be oxidised or reduced instead of (or as well as) the dissolved ions, depending on relative ease of discharge.", "The relative ease of discharge (position in the electrochemical/reactivity series) of the various ions and water present determines which species is preferentially oxidised at the anode and reduced at the cathode.", "The material of the electrodes (inert, e.g. platinum/graphite, versus reactive/active electrodes) can also affect which reactions actually occur, since an active electrode can itself participate in the reaction."]}, {"id": "3.2.5.4", "unit": 3, "topic": "T2 - Oxidation and reduction", "subtopic": "S5 - Electrolytic cells", "code": "3.2.5.4", "descriptor": "Determine the products of the electrolysis of a molten salt.", "graphical": false, "needsExplanation": true, "modelAnswer": ["In a molten ionic salt, only the cation and anion of the salt itself are present (no water to compete), so the cation is reduced at the cathode and the anion is oxidised at the anode.", "For example, electrolysis of molten NaCl produces sodium metal at the cathode (Na⁺ + e⁻ → Na) and chlorine gas at the anode (2Cl⁻ → Cl₂ + 2e⁻).", "Because there is no water present to compete for discharge, the products of molten-salt electrolysis are more straightforward to predict than for the electrolysis of an aqueous solution of the same salt."]}, {"id": "3.2.5.5", "unit": 3, "topic": "T2 - Oxidation and reduction", "subtopic": "S5 - Electrolytic cells", "code": "3.2.5.5", "descriptor": "Explain the products of the electrolysis of aqueous solutions, e.g. dilute and concentration sodium chloride(aq) and copper sulfate(aq).", "graphical": false, "needsExplanation": true, "modelAnswer": ["In aqueous electrolysis, water itself can be oxidised (to O₂) at the anode or reduced (to H₂) at the cathode, competing with the dissolved ions for discharge — the species that is easier to discharge (lower overpotential/more favourable position) is preferentially produced.", "For dilute aqueous NaCl, water is more easily reduced than Na⁺ (Na⁺ is very hard to reduce), so H₂ gas forms at the cathode; water is also more easily oxidised than dilute Cl⁻, so O₂ tends to form at the anode — but at higher (concentrated) Cl⁻ concentration, Cl₂ gas is produced at the anode instead due to overpotential effects favouring chloride discharge.", "For aqueous CuSO₄, Cu²⁺ is more easily reduced than water, so copper metal deposits at the cathode; SO₄²⁻ is very difficult to oxidise, so water is oxidised at the anode instead, producing O₂ gas."]}, {"id": "3.2.5.6", "unit": 3, "topic": "T2 - Oxidation and reduction", "subtopic": "S5 - Electrolytic cells", "code": "3.2.5.6", "descriptor": "Describe that electrolytic cells can be used in small-scale and industrial situations, including metal plating and the purification of copper.", "graphical": false, "needsExplanation": true, "modelAnswer": ["In electroplating, the object to be plated is made the cathode (so the desired metal ions are reduced and deposit onto it), and a piece of the plating metal itself is often used as the anode (dissolving to replenish the metal ions in solution).", "In copper purification (electrorefining), impure copper is used as the anode (it dissolves, releasing Cu²⁺ into solution, along with impurities), and a strip of pure copper is used as the cathode (onto which only Cu²⁺ is selectively reduced and deposited), leaving impurities behind as a sludge or in solution.", "Both processes rely on selectively controlling which species is oxidised/reduced at each electrode, by choosing appropriate electrode materials and electrolyte composition."]}, {"id": "3.2.5.7", "unit": 3, "topic": "T2 - Oxidation and reduction", "subtopic": "S5 - Electrolytic cells", "code": "3.2.5.7", "descriptor": "Calculate moles of electrons, current, time, mass of substance or volume of gas produced or used during electrolysis. (Formula: q = n(e−) × F or q = I × t).", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.5.8", "unit": 3, "topic": "T2 - Oxidation and reduction", "subtopic": "S5 - Electrolytic cells", "code": "3.2.5.8", "descriptor": "Analyse data to determine the relative amounts of product produced at each electrode in electrolysis.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.1.1.1", "unit": 4, "topic": "T1 - Properties and structure of organic materials", "subtopic": "S1 - Structure of organic compounds", "code": "4.1.1.1", "descriptor": "Identify organic molecules including alkanes, alkenes, alkynes, alcohols, aldehydes, ketones, carboxylic acids, haloalkanes, esters, amines and amides.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Each of these organic classes is defined by a characteristic functional group: alkanes have only single C–C/C–H bonds, alkenes have a C=C double bond, alkynes a C≡C triple bond, alcohols an –OH group, aldehydes a terminal –CHO group, ketones a C=O group within the carbon chain, carboxylic acids a –COOH group, haloalkanes a halogen substituent, esters a –COO– linkage, amines an –NH₂ (or substituted N) group, and amides a –CONH– group.", "Recognising these molecules relies on identifying the specific functional group(s) present in a given structural, condensed or skeletal formula.", "Some molecules may contain more than one functional group, which can give them properties or reactivity characteristic of multiple classes at once."]}, {"id": "4.1.1.2", "unit": 4, "topic": "T1 - Properties and structure of organic materials", "subtopic": "S1 - Structure of organic compounds", "code": "4.1.1.2", "descriptor": "Discriminate between class and functional groups, e.g. for OH, hydroxyl is the functional group and alcohol is the class.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A functional group is the specific atom or group of atoms responsible for the characteristic chemical behaviour of a molecule (e.g. the hydroxyl group, –OH).", "A class (or homologous series) is the broader family of compounds that share that same functional group (e.g. 'alcohols' as a class all contain the hydroxyl functional group).", "This distinction matters because the functional group name describes the specific reactive part of the molecule, whereas the class name describes the whole compound's overall category."]}, {"id": "4.1.1.3", "unit": 4, "topic": "T1 - Properties and structure of organic materials", "subtopic": "S1 - Structure of organic compounds", "code": "4.1.1.3", "descriptor": "Describe the features of a homologous series.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A homologous series is a family of compounds with the same general formula and the same functional group, differing from one another by a constant unit — typically a –CH₂– group.", "Members of the series show a gradual, predictable trend in physical properties (such as boiling point) as the length of the carbon chain increases.", "All members of the series can generally be prepared by similar methods and undergo similar characteristic chemical reactions, due to sharing the same functional group."]}, {"id": "4.1.1.4", "unit": 4, "topic": "T1 - Properties and structure of organic materials", "subtopic": "S1 - Structure of organic compounds", "code": "4.1.1.4", "descriptor": "Discriminate between saturated and unsaturated organic molecules.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A saturated organic molecule contains only single covalent bonds between carbon atoms (e.g. alkanes) — each carbon is bonded to the maximum possible number of other atoms.", "An unsaturated organic molecule contains at least one double or triple bond between carbon atoms (e.g. alkenes, alkynes), meaning fewer hydrogen atoms are bonded to those carbons than in the saturated case.", "Unsaturation typically makes a molecule more chemically reactive, since the double/triple bond can undergo addition reactions that a saturated single bond cannot."]}, {"id": "4.1.1.5", "unit": 4, "topic": "T1 - Properties and structure of organic materials", "subtopic": "S1 - Structure of organic compounds", "code": "4.1.1.5", "descriptor": "Discriminate between empirical, molecular and structural formulas.", "graphical": false, "needsExplanation": true, "modelAnswer": ["An empirical formula shows the simplest whole-number ratio of atoms of each element present in a compound (e.g. CH₂ for many alkenes).", "A molecular formula shows the actual number of atoms of each element present in one molecule of the compound (e.g. C₄H₈ for but-1-ene) — it may be a whole-number multiple of the empirical formula.", "A structural formula shows how the atoms are actually arranged and bonded together within the molecule, revealing information about connectivity (and sometimes shape) that molecular and empirical formulas do not."]}, {"id": "4.1.1.6", "unit": 4, "topic": "T1 - Properties and structure of organic materials", "subtopic": "S1 - Structure of organic compounds", "code": "4.1.1.6", "descriptor": "Determine molecular and structural formulas for organic compounds, up to C10, including simple methyl and ethyl branched chains, for various classes.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.1.1.7", "unit": 4, "topic": "T1 - Properties and structure of organic materials", "subtopic": "S1 - Structure of organic compounds", "code": "4.1.1.7", "descriptor": "Apply IUPAC rules in the nomenclature of organic compounds, up to C10, including simple methyl and ethyl branched chains, for various classes.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.1.1.8", "unit": 4, "topic": "T1 - Properties and structure of organic materials", "subtopic": "S1 - Structure of organic compounds", "code": "4.1.1.8", "descriptor": "Identify structural and stereoisomers, including geometrical (cis and trans) and optical isomers.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Structural isomers have the same molecular formula but different structural formulas (a different arrangement/connectivity of atoms) — e.g. different carbon skeletons or different positions of a functional group.", "Stereoisomers have the same molecular formula AND the same connectivity of atoms, but differ in the spatial (three-dimensional) arrangement of those atoms.", "Geometrical (cis-trans) isomers arise from restricted rotation around a C=C double bond, giving two distinct spatial arrangements of substituent groups; optical isomers arise from a chiral centre (typically a carbon bonded to four different groups), giving two non-superimposable mirror-image forms."]}, {"id": "4.1.1.9", "unit": 4, "topic": "T1 - Properties and structure of organic materials", "subtopic": "S1 - Structure of organic compounds", "code": "4.1.1.9", "descriptor": "Deduce the structural formula of geometrical (cis and trans) isomers (non-cyclic alkenes), optical isomers and isomers of the non-cyclic alkanes up to C6.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.1.1.10", "unit": 4, "topic": "T1 - Properties and structure of organic materials", "subtopic": "S1 - Structure of organic compounds", "code": "4.1.1.10", "descriptor": "Sketch the structural formula and apply IUPAC rules in the nomenclature for isomers of alkanes (non-cyclic) and alkenes (straight chain) up to C6, and for the geometrical (cis and trans) isomers of simple alkenes (non-cyclic).", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.1.1.11", "unit": 4, "topic": "T1 - Properties and structure of organic materials", "subtopic": "S1 - Structure of organic compounds", "code": "4.1.1.11", "descriptor": "Determine the structural formula of optical isomers for simple organic compounds.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.1.1.12", "unit": 4, "topic": "T1 - Properties and structure of organic materials", "subtopic": "S1 - Structure of organic compounds", "code": "4.1.1.12", "descriptor": "Identify chiral carbon atoms.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.1.1.13", "unit": 4, "topic": "T1 - Properties and structure of organic materials", "subtopic": "S1 - Structure of organic compounds", "code": "4.1.1.13", "descriptor": "Analyse data to determine the structural, molecular and empirical formula of organic compound and the percentage composition of elements in organic compounds.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.1.2.1", "unit": 4, "topic": "T1 - Properties and structure of organic materials", "subtopic": "S2 - Physical properties and trends", "code": "4.1.2.1", "descriptor": "Explain the trends (melting point, boiling point, volatility, solubility in water and organic solvents) within and between homologous series (alkanes, alkenes, alcohols, carboxylic acids) in terms of intermolecular and intramolecular bonding, e.g. dispersion forces, dipole-dipole interactions and hydrogen bonds.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Within a homologous series, melting/boiling points increase (and volatility decreases) as chain length increases, because longer chains have more surface area for dispersion forces to act over, requiring more energy to overcome.", "Between different homologous series of similar chain length, compounds capable of hydrogen bonding (alcohols, carboxylic acids) have notably higher melting/boiling points than those relying only on weaker dipole-dipole forces or dispersion forces (e.g. alkanes, alkenes), because hydrogen bonds are stronger and require more energy to break.", "Solubility in water is greater for molecules that can hydrogen-bond with water molecules (alcohols, carboxylic acids, especially with shorter carbon chains); solubility in water decreases as the non-polar hydrocarbon chain length increases, since the non-polar portion cannot interact favourably with polar water.", "Solubility in non-polar organic solvents follows the opposite trend — non-polar or largely non-polar molecules (alkanes, longer-chain compounds) dissolve more readily in non-polar solvents, consistent with the general principle 'like dissolves like'."]}, {"id": "4.1.2.2", "unit": 4, "topic": "T1 - Properties and structure of organic materials", "subtopic": "S2 - Physical properties and trends", "code": "4.1.2.2", "descriptor": "Analyse data to determine the physical properties of an homologous series, trends in melting point, boiling point, volatility and the solubility alkanes, alkenes, alcohols and carboxylic acids.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.1.3.1", "unit": 4, "topic": "T1 - Properties and structure of organic materials", "subtopic": "S3 - Organic reactions and reaction pathways", "code": "4.1.3.1", "descriptor": "Identify that an organic compound displays characteristic chemical properties and undergoes specific reactions based on the functional group present.", "graphical": false, "needsExplanation": true, "modelAnswer": ["The functional group of an organic molecule is the primary determinant of how it will react chemically, largely independent of the rest of the (unreactive) carbon chain.", "This means molecules from the same homologous series undergo very similar characteristic reactions (e.g. all alcohols can be oxidised in a similar way), regardless of chain length.", "Recognising the functional group present in a molecule is therefore the key first step in predicting what reactions it can undergo and what products would form."]}, {"id": "4.1.3.2", "unit": 4, "topic": "T1 - Properties and structure of organic materials", "subtopic": "S3 - Organic reactions and reaction pathways", "code": "4.1.3.2", "descriptor": "Determine, using equations, the reaction of alkanes with halogens (X2), haloalkanes with halogens (X2), sodium hydroxide and ammonia, alkenes with water, halogens(X2), hydrogen (H2) and hydrogen halides (HX), alcohols with hydrogen halides (HX), carboxylic acid with alcohol to form esters, and with amines to form amides.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.1.3.3", "unit": 4, "topic": "T1 - Properties and structure of organic materials", "subtopic": "S3 - Organic reactions and reaction pathways", "code": "4.1.3.3", "descriptor": "Determine, using equations, reactions including the oxidation of alcohols, combustion of alkanes and alcohols, addition of alkenes to form poly(alkenes), reduction of alkynes and alkenes to form alkanes, elimination of haloalkanes to form alkenes.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.1.3.4", "unit": 4, "topic": "T1 - Properties and structure of organic materials", "subtopic": "S3 - Organic reactions and reaction pathways", "code": "4.1.3.4", "descriptor": "Identify reactions as addition, elimination, substitution or redox (oxidation-reduction). (Reaction mechanism for substitution and elimination reactions are not required.)", "graphical": false, "needsExplanation": true, "modelAnswer": ["Addition reactions occur when two reactants combine to form a single product, typically across a double or triple bond (e.g. an alkene reacting with H₂ or a halogen), with no atoms lost.", "Elimination reactions occur when a single reactant splits into two products, typically losing a small molecule (e.g. HX or H₂O) to form a double bond (e.g. a haloalkane forming an alkene).", "Substitution reactions occur when one atom or group in a molecule is replaced by another atom or group (e.g. a haloalkane reacting with OH⁻ to replace the halogen).", "Redox reactions involve a change in oxidation state of at least one atom (electron transfer), such as the oxidation of an alcohol to an aldehyde/ketone or carboxylic acid."]}, {"id": "4.1.3.5", "unit": 4, "topic": "T1 - Properties and structure of organic materials", "subtopic": "S3 - Organic reactions and reaction pathways", "code": "4.1.3.5", "descriptor": "Determine the primary, secondary and tertiary carbon atoms in haloalkanes and alcohols.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.1.3.6", "unit": 4, "topic": "T1 - Properties and structure of organic materials", "subtopic": "S3 - Organic reactions and reaction pathways", "code": "4.1.3.6", "descriptor": "Describe the acid-base properties of carboxylic acids and amines.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Carboxylic acids act as weak Brønsted-Lowry acids, partially ionising in water to donate a proton from the –COOH group, forming a carboxylate ion (–COO⁻) and H₃O⁺.", "Amines act as weak Brønsted-Lowry bases, with the lone pair on the nitrogen atom able to accept a proton from water, forming an ammonium-type cation (–NH₃⁺) and OH⁻.", "Both are 'weak' in this context because these proton-transfer reactions with water reach only a partial equilibrium, rather than proceeding to completion."]}, {"id": "4.1.3.7", "unit": 4, "topic": "T1 - Properties and structure of organic materials", "subtopic": "S3 - Organic reactions and reaction pathways", "code": "4.1.3.7", "descriptor": "Explain that esterification is a reversible reaction.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Esterification (a carboxylic acid reacting with an alcohol to form an ester and water) does not go to completion — it establishes an equilibrium between reactants and products.", "Because it is reversible, the reverse reaction (hydrolysis of the ester, usually catalysed by acid or base, splitting it back into the carboxylic acid and alcohol) can also occur under suitable conditions.", "This reversibility means Le Châtelier's principle can be applied to esterification — e.g. removing water as it forms, or using excess of one reactant, shifts the equilibrium to favour a higher yield of ester."]}, {"id": "4.1.3.8", "unit": 4, "topic": "T1 - Properties and structure of organic materials", "subtopic": "S3 - Organic reactions and reaction pathways", "code": "4.1.3.8", "descriptor": "Discriminate between alkanes and alkenes using bromine water; primary, secondary and tertiary alcohols using acidified potassium dichromate (VI) and potassium manganate (VII).", "graphical": false, "needsExplanation": true, "modelAnswer": ["Alkenes rapidly decolourise orange bromine water (via an addition reaction across the C=C double bond), while alkanes do not react with bromine water under normal conditions (no colour change) — this is a standard chemical test to distinguish the two classes.", "Primary and secondary alcohols can be oxidised by acidified potassium dichromate(VI) or potassium manganate(VII), causing a visible colour change (dichromate: orange to green; manganate: purple to colourless/brown) as the oxidising agent is reduced.", "Tertiary alcohols cannot be oxidised by these reagents (they lack a hydrogen on the carbon bonded to the –OH group needed for the oxidation to proceed), so no colour change is observed, distinguishing them from primary/secondary alcohols."]}, {"id": "4.1.3.9", "unit": 4, "topic": "T1 - Properties and structure of organic materials", "subtopic": "S3 - Organic reactions and reaction pathways", "code": "4.1.3.9", "descriptor": "Apply Markovnikov's rule to determine the products for addition reactions of alkenes with hydrogen halides (HX) and water.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.1.3.10", "unit": 4, "topic": "T1 - Properties and structure of organic materials", "subtopic": "S3 - Organic reactions and reaction pathways", "code": "4.1.3.10", "descriptor": "Determine reaction pathways, including reagents, condition and chemical equations, given the starting materials and the product/s formed.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.1.3.11", "unit": 4, "topic": "T1 - Properties and structure of organic materials", "subtopic": "S3 - Organic reactions and reaction pathways", "code": "4.1.3.11", "descriptor": "Interpret chemical tests to distinguish between alkanes and alkenes; and primary, secondary and tertiary alcohols.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.1.4.1", "unit": 4, "topic": "T1 - Properties and structure of organic materials", "subtopic": "S4 - Organic materials: structure and function", "code": "4.1.4.1", "descriptor": "Describe the structural features of amino acids, tripeptides, monosaccharides and disaccharides; polyethene (LDPE and HDPE), polypropene (syntactic, isotactic and atactic) and polytetrafluorethene (Teflon); polylactic acid (PLA), polyamide (nylon) and polyester.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Amino acids share a common structure: a central (alpha) carbon bonded to an amine group (–NH₂), a carboxylic acid group (–COOH), a hydrogen atom, and a variable 'R' side group that differs between amino acids.", "Tripeptides are three amino acids joined together by peptide (amide) bonds, formed via condensation reactions with loss of water at each linkage.", "Monosaccharides are single sugar units (e.g. glucose); disaccharides are two monosaccharide units joined together by a glycosidic bond, again formed via a condensation reaction.", "LDPE and HDPE (low/high-density polyethene) differ in the degree of chain branching — LDPE has more branching (lower density, more flexible), HDPE has less branching (higher density, more rigid); polypropene's tacticity (syndiotactic/isotactic/atactic) describes the regularity of methyl group orientation along the chain, affecting how tightly chains can pack and crystallise; PTFE (Teflon) has a carbon backbone fully substituted with fluorine atoms, giving it exceptional chemical inertness.", "PLA, nylon (a polyamide) and polyester are all condensation polymers, formed from monomers linked via ester or amide bonds respectively, with small molecules (often water) released at each linkage."]}, {"id": "4.1.4.2", "unit": 4, "topic": "T1 - Properties and structure of organic materials", "subtopic": "S4 - Organic materials: structure and function", "code": "4.1.4.2", "descriptor": "Explain how properties, including strength, density and biodegradability of polymers can be related to the structures of the materials.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Greater chain branching generally reduces how closely polymer chains can pack together, lowering density and crystallinity, and typically reducing strength and rigidity.", "Stronger intermolecular forces between chains (e.g. hydrogen bonding in nylon, or extensive dispersion forces in linear, unbranched chains) increase strength and rigidity by resisting chains sliding past one another.", "Polymers containing functional groups susceptible to hydrolysis (e.g. the ester linkages in PLA/polyester, or amide linkages in natural proteins) can be broken down by water/enzymes over time, making them biodegradable — unlike polymers with only strong, unreactive C–C and C–F backbones (e.g. polyethene, PTFE), which resist breakdown and are not readily biodegradable."]}, {"id": "4.1.4.3", "unit": 4, "topic": "T1 - Properties and structure of organic materials", "subtopic": "S4 - Organic materials: structure and function", "code": "4.1.4.3", "descriptor": "Explain the acid-base properties of 2-amino acids, including the formation of zwitterions.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A 2-amino acid contains both an acidic –COOH group and a basic –NH₂ group on the same molecule, so it can act as either an acid or a base depending on the surrounding pH.", "At intermediate (near-neutral) pH, an internal proton transfer occurs: the –COOH group donates its proton to the –NH₂ group, forming a zwitterion — a single molecule carrying both a positive (–NH₃⁺) and a negative (–COO⁻) charge, with an overall net charge of zero.", "In more acidic solution, the zwitterion's –COO⁻ group can accept a proton, giving the molecule an overall positive charge; in more basic solution, the –NH₃⁺ group can donate its proton, giving the molecule an overall negative charge — this pH-dependent charge behaviour underlies electrophoretic separation of amino acids."]}, {"id": "4.1.5.1", "unit": 4, "topic": "T1 - Properties and structure of organic materials", "subtopic": "S5 - Analytical techniques", "code": "4.1.5.1", "descriptor": "Explain how amino acids can be separated and identified by paper/TLC chromatography, including intermolecular forces/solubility in mobile and stationary phase and retention (RF) values.", "graphical": false, "needsExplanation": true, "modelAnswer": ["In paper/TLC chromatography, different amino acids are carried at different rates by the moving solvent (mobile phase) across the stationary paper/plate (stationary phase), based on their relative solubility/affinity for each phase.", "An amino acid's relative attraction (via intermolecular forces, e.g. hydrogen bonding or dispersion forces) to the polar stationary phase versus the mobile solvent phase determines how far it travels relative to the solvent front — amino acids more attracted to the stationary phase move more slowly.", "The retention factor RF = (distance moved by the amino acid) / (distance moved by the solvent) is a characteristic, reproducible value for a given amino acid under fixed conditions, allowing unknown spots to be identified by comparison with known RF values or reference standards."]}, {"id": "4.1.5.2", "unit": 4, "topic": "T1 - Properties and structure of organic materials", "subtopic": "S5 - Analytical techniques", "code": "4.1.5.2", "descriptor": "Explain how amino acids can be separated and analysed by electrophoresis, including pH of buffer, isoelectric points, and movement of charged ions.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Electrophoresis separates amino acids based on their net electrical charge at a given pH, by applying an electric field across a buffered gel or medium containing the sample.", "The isoelectric point (pI) is the specific pH at which a particular amino acid exists predominantly as its zwitterion, carrying zero net charge — at this pH, that amino acid does not migrate toward either electrode.", "At a buffer pH below an amino acid's pI, the amino acid carries an overall positive charge and migrates toward the negative electrode (cathode); at a buffer pH above its pI, it carries an overall negative charge and migrates toward the positive electrode (anode) — different amino acids, with different pI values, therefore separate from one another at a given buffer pH."]}, {"id": "4.1.5.3", "unit": 4, "topic": "T1 - Properties and structure of organic materials", "subtopic": "S5 - Analytical techniques", "code": "4.1.5.3", "descriptor": "Analyse data, including paper/TLC chromatograms and electrophoresis to determine the identity of amino acids and retention factors.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.1.5.4", "unit": 4, "topic": "T1 - Properties and structure of organic materials", "subtopic": "S5 - Analytical techniques", "code": "4.1.5.4", "descriptor": "Analyse data from spectra, including mass spectroscopy and infrared to determine the identity and structure of organic molecules.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.2.1.1", "unit": 4, "topic": "T2 - Chemical synthesis and design", "subtopic": "S1 - Chemical synthesis", "code": "4.2.1.1", "descriptor": "Explain that reagents and reaction conditions are chosen to optimise the yield and rate for chemical synthesis processes, including the production of ammonia (Haber process) and sulfuric acid (contact process).", "graphical": false, "needsExplanation": true, "modelAnswer": ["Because many industrial syntheses (e.g. the Haber and contact processes) involve reversible, exothermic equilibrium reactions, conditions must balance competing demands: higher temperature increases reaction rate but (by Le Châtelier's principle) shifts equilibrium away from the exothermic product side, reducing yield.", "Compromise conditions are therefore typically used — a moderately high temperature (balancing rate and yield) and, where a decrease in gas moles favours products, a high pressure (increasing yield, and also increasing rate via higher concentration/collision frequency).", "A catalyst is commonly used to increase the rate of reaching equilibrium at a more moderate (compromise) temperature, without needing to sacrifice yield by using an excessively high temperature."]}, {"id": "4.2.1.2", "unit": 4, "topic": "T2 - Chemical synthesis and design", "subtopic": "S1 - Chemical synthesis", "code": "4.2.1.2", "descriptor": "Describe, using equations, the production of ammonia by the Haber process; production of sulfuric acid using the contact process; production of ethanol from fermentation and the hydration of ethene; operation of a hydrogen fuel cell under acidic and alkaline conditions.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Haber process: N₂(g) + 3H₂(g) ⇌ 2NH₃(g), an exothermic, reversible reaction typically run at a compromise moderate-high temperature, high pressure, and with an iron catalyst.", "Contact process: sulfur is burned/converted to SO₂, which is catalytically oxidised (V₂O₅ catalyst) to SO₃ (2SO₂ + O₂ ⇌ 2SO₃), and SO₃ is then reacted with water (usually via an intermediate step, to avoid a hazardous fog) to form H₂SO₄.", "Ethanol production: fermentation converts glucose to ethanol and CO₂ using yeast enzymes (C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂) under anaerobic conditions; alternatively, ethene can be directly hydrated with steam over a catalyst (C₂H₄ + H₂O ⇌ C₂H₅OH).", "Hydrogen fuel cells: under acidic conditions, H₂ is oxidised at the anode (H₂ → 2H⁺ + 2e⁻) and O₂ is reduced at the cathode (O₂ + 4H⁺ + 4e⁻ → 2H₂O); under alkaline conditions, H₂ is oxidised using OH⁻ (H₂ + 2OH⁻ → 2H₂O + 2e⁻) and O₂ is reduced to produce OH⁻ (O₂ + 2H₂O + 4e⁻ → 4OH⁻) — in both cases, the overall reaction is the same (H₂ + ½O₂ → H₂O), generating electrical energy directly from a spontaneous redox reaction."]}, {"id": "4.2.1.3", "unit": 4, "topic": "T2 - Chemical synthesis and design", "subtopic": "S1 - Chemical synthesis", "code": "4.2.1.3", "descriptor": "Calculate the yield of chemical synthesis reactions by comparing stoichiometric quantities with actual quantities and by determining limiting reagents and/or reaction conditions.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.2.1.4", "unit": 4, "topic": "T2 - Chemical synthesis and design", "subtopic": "S1 - Chemical synthesis", "code": "4.2.1.4", "descriptor": "Analyse and interpret data to determine the impact of reagents and reaction conditions on yield and rate of chemical synthesis processes.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.2.2.1", "unit": 4, "topic": "T2 - Chemical synthesis and design", "subtopic": "S2 - Macromolecules: polymers, proteins and carbohydrates", "code": "4.2.2.1", "descriptor": "Describe, using equations, how addition polymers, including polyethene (LDPE and HDPE), polypropene and polytetrafluorethene, can be produced from their monomers; condensation polymers, including polysaccharides (carbohydrates), polylactic acid (PLA), polyamide (proteins and nylon) and polyester, can be produced from their monomers.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Addition polymerisation involves unsaturated monomers (containing a C=C double bond) joining together directly, with the double bond opening up to form new single bonds between monomer units — no atoms or small molecules are lost, so the polymer's formula is simply a repeating multiple of the monomer's formula (e.g. n C₂H₄ → –(CH₂–CH₂)ₙ–).", "Condensation polymerisation involves monomers (typically each with two reactive functional groups) joining together with the elimination of a small molecule, usually water, at each new linkage formed (e.g. an –OH and a –COOH group combining to form an ester link, releasing H₂O).", "This same condensation principle applies to biological macromolecules: polysaccharides form from monosaccharide monomers joined by glycosidic bonds (with loss of water), and proteins (natural polyamides) form from amino acid monomers joined by peptide bonds (also with loss of water) — directly analogous to how synthetic polyamides (nylon) and polyesters are formed."]}, {"id": "4.2.2.2", "unit": 4, "topic": "T2 - Chemical synthesis and design", "subtopic": "S2 - Macromolecules: polymers, proteins and carbohydrates", "code": "4.2.2.2", "descriptor": "Apply amino acid symbols to construct and name tripeptides.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.2.2.3", "unit": 4, "topic": "T2 - Chemical synthesis and design", "subtopic": "S2 - Macromolecules: polymers, proteins and carbohydrates", "code": "4.2.2.3", "descriptor": "Identify that tripeptides are formed when amino acid monomers are joined by peptide bonds.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A peptide bond is an amide linkage (–CO–NH–) formed between the carboxylic acid group of one amino acid and the amine group of another, with the elimination of a water molecule (a condensation reaction).", "A tripeptide is formed when three amino acid monomers are joined together by two such peptide bonds in a chain.", "The order in which the different amino acids are joined together (the sequence) determines the specific identity and properties of the resulting tripeptide, even if the same three amino acids are used in a different order."]}, {"id": "4.2.2.4", "unit": 4, "topic": "T2 - Chemical synthesis and design", "subtopic": "S2 - Macromolecules: polymers, proteins and carbohydrates", "code": "4.2.2.4", "descriptor": "Identify that disaccharides are formed when monosaccharides monomers are joined by glycosidic bonds.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A glycosidic bond is a type of covalent linkage formed between two monosaccharide units, via a condensation reaction that releases a molecule of water.", "A disaccharide consists of exactly two monosaccharide units joined together by one glycosidic bond (e.g. sucrose is formed from glucose and fructose).", "This is directly analogous to how amino acids join via peptide bonds and how ester/amide monomers join in synthetic condensation polymers — all involve linking monomer units with the loss of a small molecule."]}];
